                match = True
            elif isinstance(val_old, (int, float)) and isinstance(val_new, (int, float)):
                if abs(float(val_old) - float(val_new)) < 1e-9:
                    match = True

            if not match:
                modified_employees.append({
                    "id": str(emp_id),
                    "field": col,
                    "old_value": val_old,
                    "new_value": val_new
                })

# Final cleaning of values for JSON
def json_serializable(val):
    if pd.isna(val): return None
    if isinstance(val, (pd.Timestamp, pd.DatetimeIndex)):
        return val.isoformat()
    if isinstance(val, (int, float)):
        if val == int(val):
            return int(val)
        return float(val)
    return str(val)

for item in modified_employees:
    item["old_value"] = json_serializable(item["old_value"])
    item["new_value"] = json_serializable(item["new_value"])

report = {
    "deleted_employees": deleted_employees,
    "modified_employees": sorted(modified_employees, key=lambda x: (x["id"], x["field"]))
}

with open("diff_report.json", "w") as f:
    json.dump(report, f, indent=2)

print("Report generated successfully.")
