            else:
                if table[0][0].startswith("EMP"):
                    all_rows.extend(table)
                else:
                    all_rows.extend(table[1:])

pdf_df = pd.DataFrame(all_rows, columns=headers)

# Clean all columns in PDF
for col in pdf_df.columns:
    pdf_df[col] = pdf_df[col].apply(clean_val)

